public EventMessage decode(ParsableByteArray emsgData) {
  String schemeIdUri;
  String value;
  long durationMs;
  long id;
  byte[] messageData;
  try {
    schemeIdUri = Assertions.checkNotNull(emsgData.readNullTerminatedString());
    value = Assertions.checkNotNull(emsgData.readNullTerminatedString());
    durationMs = emsgData.readUnsignedInt();
    id = emsgData.readUnsignedInt();
    messageData = Arrays.copyOfRange(emsgData.data, emsgData.getPosition(), emsgData.limit());
  } catch (UnsupportedCharsetException | NullPointerException e) {
    // Handle the exception, e.g., log it or take appropriate action.
    e.printStackTrace();
    return null; // or re-throw, or handle as appropriate
  }
  return new EventMessage(schemeIdUri, value, durationMs, id, messageData);
}
